import XCTest
final class SummaryDesignFlowTests:XCTestCase {
 func testQuickLogPinsAndHighlights()throws{let app=XCUIApplication();app.launchArguments += ["-AppleInterfaceStyle","Dark"];app.launch();let quick=app.buttons["summary-quick-mood"].firstMatch;XCTAssertTrue(quick.waitForExistence(timeout:10));let directory=FileManager.default.urls(for:.documentDirectory,in:.userDomainMask)[0];try XCUIScreen.main.screenshot().pngRepresentation.write(to:directory.appendingPathComponent("28-summary-dark.png"));quick.tap();XCTAssertTrue(app.buttons["record-save"].waitForExistence(timeout:5));app.buttons["닫기"].firstMatch.tap();let edit=app.buttons["summary-pins-edit"].firstMatch;for _ in 0..<5{if edit.isHittable{break};app.swipeUp()};XCTAssertTrue(edit.isHittable);edit.tap();XCTAssertTrue(app.buttons["summary-pin-걸음"].waitForExistence(timeout:5));app.buttons["완료"].firstMatch.tap();let highlights=app.buttons["summary-highlights-all"].firstMatch;for _ in 0..<15{if highlights.isHittable{break};app.swipeUp()};XCTAssertTrue(highlights.isHittable);highlights.tap();let chart=app.buttons["summary-highlight-운동"].firstMatch;XCTAssertTrue(chart.waitForExistence(timeout:5));for _ in 0..<4{if chart.isHittable{break};app.swipeUp()};try XCUIScreen.main.screenshot().pngRepresentation.write(to:directory.appendingPathComponent("29-summary-highlights.png"));app.terminate()}
}
